export type ProductionJSON = null | boolean | number | string | ProductionJSON[] | {[key: string]: ProductionJSON};
export type ProductionHost = 'codex' | 'workbuddy';
export interface ProductionAccount {id: string; name: string; platform: string; url: string; note: string; tags: string[]; images: string[]; avatarAssetHash?: string | null; reportIds: string[]; createdAt: string; updatedAt: string; deletedAt: string | null}
export interface ProductionReport {id: string; title: string; type: string; accountIds: string[]; sourceUrl: string | null; collectedAt: string | null; pages: {id: string; title: string; assetHash: string}[]; pageId: string; meta: ProductionJSON; createdAt: string; updatedAt: string; deletedAt: string | null}
export interface ProductionReference {id: string; url: string | null; title: string; platform: string; originalText: string; correctedText: string; segments: {startMs: number; endMs: number; text: string}[]; corrections: {original: string; corrected: string; reason: string}[]; analysis: string; mediaAssetHash: string | null; subtitleAssetHash: string | null}
export interface ProductionCandidate {id: string; text: string}
export interface ProductionPackaging {titles: ProductionCandidate[]; coverTexts: ProductionCandidate[]; intros: ProductionCandidate[]; selectedTitleId: string | null; selectedCoverTextId: string | null; selectedIntroId: string | null}
export interface ProductionSuggestion {id: string; bodyHash: string; quote: string; replacement: string; reason: string; status: 'pending'|'accepted'|'rejected'}
export interface ProductionAnnotation {id: string; bodyHash: string; quote: string; text: string; status: 'open'|'resolved'}
export interface ProductionFilming {shots: {id: string; quote: string; visual: string; owner: 'screen'|'self'|'editing'; done: boolean}[]; readThroughBodyHash: string|null; recordedBodyHash: string|null}
export interface ProductionCreation {contentId: string; tNumber: string; stage: 'idea'|'research'|'references'|'transcription'|'analysis'|'narrative'|'writing'|'ready'|'published'; kind: 'tutorial'|'spoken'|'science'|'other'; references: ProductionReference[]; analysis: string; narrative: string; suggestions: ProductionSuggestion[]; annotations: ProductionAnnotation[]; packaging: ProductionPackaging; confirmedBodyHash: string | null; filming?: ProductionFilming; createdAt: string; updatedAt: string}
export type ProductionArtifactKind = 'report'|'research'|'transcript'|'analysis'|'narrative'|'draft'|'packaging'|'feedback'|'knowledge';
export interface ProductionArtifact {id: string; kind: ProductionArtifactKind; title: string; text: string; assetHash: string | null; data: ProductionJSON}
export interface ProductionResult {summary: string; artifacts: ProductionArtifact[]}
export interface ProductionAttempt {id: string; host: ProductionHost; status: 'created'|'claimed'|'waiting-user'|'waiting-permission'|'submitted'|'accepted'|'failed'|'cancelled'; claimToken: string | null; workerId: string | null; progress: number; message: string; failure: {code: string; message: string} | null; result: ProductionResult | null; receipt: {sha256: string; taskId: string; attemptId: string; requestHash: string; resultHash: string} | null; createdAt: string; updatedAt: string}
export interface ProductionFixedRequest {prompt: string; parameters: ProductionJSON; tools: string[]; budget: {amount: number; currency: 'REQ'}; bodyHash: string | null}
export interface ProductionTask {id: string; kind: 'research'|'transcription'|'analysis'|'writing'|'packaging'|'review'; title: string; contentId: string | null; accountId: string | null; request: ProductionFixedRequest; requestHash: string; attempts: ProductionAttempt[]; activeAttemptId: string; createdAt: string; updatedAt: string}
export interface ProductionRecord {id: string; contentId: string | null; text: string; source: string; createdAt: string}
export interface ProductionKnowledge extends ProductionRecord {status: 'candidate'|'accepted'|'rejected'; updatedAt: string}
export interface ProductionCost {id: string; taskId: string; attemptId: string; requestId: string; service: string; status: 'reserved'|'estimated'|'measured'|'actual'|'billed'|'unknown'|'cancelled'; amount: number | null; currency: string; usage: ProductionJSON; createdAt: string; updatedAt: string}
export interface ProductionArchive {category:import('./production-archive-category.mjs').ProductionArchiveCategory;directory:string;taskId:string;attemptId:string;receiptHash:string;status:'submitted'|'accepted';warnings:string[];ready:boolean}
export interface ProductionSnapshot {archiveWarnings?:string[];mutationId?: string; schemaVersion: 1; nextTNumber: number; accounts: ProductionAccount[]; reports: ProductionReport[]; creations: ProductionCreation[]; tasks: ProductionTask[]; feedback: ProductionRecord[]; knowledge: ProductionKnowledge[]; costs: ProductionCost[]; editToken: string; missingAssetHashes?: string[]}
export type ProductionMutation = 'adoptRadarResult'|'decideRadarCandidate'|'enable'|'saveAccount'|'trashAccount'|'restoreAccount'|'saveReport'|'trashReport'|'setReportPosition'|'ensureCreation'|'saveCreation'|'recordFeedback'|'recordKnowledge'|'decideKnowledge'|'createTask'|'claimTask'|'progressTask'|'failTask'|'cancelTask'|'retryTask'|'submitTask'|'acceptTask'|'reserveCost'|'recordCost'|'reconcileCost';
export interface ProductionHistoryVersion {transactionId: string; revision: number; at: string; operation: string; source: string; author: string|null; reason: string|null; beforeBody: string|null; afterBody: string|null; bodyTruncated: boolean; summary: {removed: string; added: string; beforeCharacters: number; afterCharacters: number}}
export interface ProductionHistory {versions: ProductionHistoryVersion[]; truncated: boolean; limit: number; scanLimit: number; entryLimit: number; responseBytesLimit: number}
export interface ProductionHistorySummary extends Omit<ProductionHistory, 'versions'> {versions: Omit<ProductionHistoryVersion, 'beforeBody'|'afterBody'>[]}
export interface ProductionContext {snapshot: ProductionSnapshot; task: ProductionTask | null; attempt: ProductionAttempt | null; account: ProductionAccount | null; content: {id: string; title: string; body: string; bodyHash: string; editToken: string} | null; creation: ProductionCreation | null; knowledge: ProductionKnowledge[]; history: ProductionHistorySummary|null}
export interface ProductionLibrary {rebuildProductionArchive(taskId:string):ProductionArchive;readProductionCreation(contentId: string): {content: {id: string; title: string; body: string; bodyHash: string; editToken: string; deletedAt: string | null}; creation: ProductionCreation | null; productionToken: string; history: ProductionHistory}; readProduction(): ProductionSnapshot; readProductionContext(taskId?: string, attemptId?: string): ProductionContext; mutateProduction(op: ProductionMutation, input: Record<string, unknown>, options?: {mutationId?: string}): ProductionSnapshot; saveProductionDraft(contentId: string, input: {body: string; expectedBodyHash: string; expectedProductionToken: string; creationPatch: Partial<ProductionCreation>}, editToken: string, options?: {mutationId?: string}): unknown; reserveProductionTool(input: Record<string, unknown>, options?: {mutationId?: string}): ProductionSnapshot}
